import sys, inspect, json
sys.path.insert(0, sys.argv[1])
import docopt as M
def rawsig(o):
    try: s=inspect.signature(o)
    except (ValueError,TypeError): return None
    ps=[]
    for n,p in s.parameters.items():
        a=p.annotation; d=p.default
        ps.append([p.kind.name,n,(a if isinstance(a,str) else (getattr(a,'__name__',None) or str(a))) if a is not p.empty else None,
                   None if d is p.empty else (d.__name__ if inspect.isclass(d) else repr(d))])
    r=s.return_annotation
    return [ps,(r if isinstance(r,str) else (getattr(r,'__name__',None) or str(r))) if r is not s.empty else None]
out={}
for n in sorted(vars(M)):
    if n.startswith("__") and n!="__version__": continue
    o=vars(M)[n]
    if inspect.isclass(o) and o.__module__=="docopt":
        e={"kind":"class","bases":[b.__name__ for b in o.__bases__],"members":{}}
        for m,v in sorted(vars(o).items()):
            if m.startswith("__") and m not in ("__init__","__eq__","__hash__","__repr__","__getattr__"): continue
            if isinstance(v,property): e["members"][m]=["property",rawsig(v.fget)]
            elif isinstance(v,classmethod): e["members"][m]=["classmethod",rawsig(v.__func__)]
            elif isinstance(v,staticmethod): e["members"][m]=["staticmethod",rawsig(v.__func__)]
            elif inspect.isfunction(v): e["members"][m]=["method",rawsig(v)]
            else: e["members"][m]=["attr",repr(v)]
        if hasattr(o,"_fields"): e["fields"]=list(o._fields)
        out[n]=e
    elif inspect.isfunction(o) and o.__module__=="docopt":
        out[n]={"kind":"func","sig":rawsig(o)}
    elif n=="__version__" or n=="__all__":
        out[n]={"kind":"data","value":o}
    elif inspect.isclass(o) or inspect.isfunction(o):
        out[n]={"kind":"alias-or-import","target":getattr(o,"__qualname__",str(o))}
    else:
        out[n]={"kind":"other","repr":repr(o)[:80]}
print(json.dumps(out,indent=1,sort_keys=True,default=str))
